const response = $input.first().json;
const body = response.body;
if (!body || typeof response.statusCode !== 'number') throw new Error('lifecycle readback unavailable');
if (response.statusCode === 200 && body.schema === 'N8nMomentumLifecycle@v1') return [{json:{live:true,receipt:body}}];
const shadowBoundaries = ['momentum_lifecycle_disabled','momentum_monitor_admission_unproven'];
if (response.statusCode === 403 && body.state === 'REFUSED' && body.monitor_stage === 'shadow' && shadowBoundaries.includes(body.reason)) return [{json:{live:false,refusal:body.reason,acceptance:'NOT_MEASURED'}}];
throw new Error('lifecycle readback unexpected refusal or stale/missing admitted receipt');

const r = $input.first().json.receipt;
if (r.schema !== 'N8nMomentumLifecycle@v1') throw new Error('lifecycle receipt absent or refused');
if (typeof r.as_of !== 'string' || !/(Z|[+-]\d{2}:\d{2})$/.test(r.as_of)) throw new Error('lifecycle timestamp must be zoned');
const age = Date.now() - Date.parse(r.as_of);
if (!Number.isFinite(age) || age < 0 || age > 600000) throw new Error('lifecycle receipt stale');
if (!/^[0-9a-f]{40}$/.test(r.source_sha || '')) throw new Error('lifecycle SHA missing');
if (!Array.isArray(r.incidents)) throw new Error('lifecycle incident list missing');
// P1 delivery is host-owned; this error is also routed by the existing incident workflow.
if (r.incidents.some(i => i.severity === 'P1')) throw new Error('momentum lifecycle P1 evidence failure; inspect host receipt');
return [{json:{schema:r.schema,as_of:r.as_of,source_sha:r.source_sha,acceptance:r.acceptance,
  incidents:r.incidents.length,recovery_held:(r.recovery?.held || []).map(x => x.reason)}}];

const response = $input.first().json;
const body = response.body;
if (response.statusCode !== 200 || !body || body.lane_id !== 'momentum-lifecycle-monitor') throw new Error('shadow last-run projection unavailable');
const r = body.last;
if (!r || r.mode !== 'dry_run' || r.state !== 'RUN_DONE' || r.exit_code !== 0) throw new Error('shadow dry-run completion not proven');
const stamps = [r.requested_at,r.started_at,r.finished_at];
if (stamps.some(x => typeof x !== 'string' || !/(Z|[+-]\d{2}:\d{2})$/.test(x))) throw new Error('shadow timestamps must be zoned');
const times = stamps.map(Date.parse);
if (times.some(x => !Number.isFinite(x)) || !(times[0] <= times[1] && times[1] <= times[2])) throw new Error('shadow durable chain incomplete');
if (Date.now()-times[2] < 0 || Date.now()-times[2] > 600000) throw new Error('shadow run metadata stale');
// Compact last-run API does not expose receipt SHA or output-effect counters. Do not invent them.
return [{json:{phase:'SHADOW_OBSERVATION',run_id:r.run_id,requested_started_finished:'PROVEN',
  receipt_ref:r.receipt_ref,source_sha:'NOT_MEASURED',zero_business_effects:'NOT_MEASURED',
  natural_trigger:'NOT_MEASURED',acceptance:'NOT_MEASURED',
  next_action:'Correlate exact-host RunReceipt, source SHA, disjoint lock, output effects and natural n8n execution before advancement'}}];
